SELECT p.first_name, p.last_name, p.email
FROM prof p
WHERE p.teachingability > (SELECT AVG(teachingability) FROM prof)
  AND p.prof_id IN (
      SELECT prof_id FROM RA GROUP BY prof_id HAVING COUNT(student_id) >= 2
  );

SELECT SUM(CAST(weight AS REAL) / (CAST(height AS REAL) * CAST(height AS REAL))) / COUNT(coachID) AS avg_bmi
FROM Master m JOIN HOF h ON m.hofID = h.hofID
WHERE m.coachID IS NOT NULL;

SELECT SUM(CAST(W AS REAL) / (W + L + T)) / COUNT(*) AS avg_winning_rate
FROM SeriesPost
WHERE year = 2000 AND (tmIDWinner = 'BUF' OR tmIDLoser = 'BUF');
